// MT2009_PLUS_WAR_RANK_KEEP_V1 (ended) (server-patches/warrankkeep): when the war of two guilds ended on this core.
// A killing blow of a war stuns its victim, and the death (CHARACTER::Dead) comes three seconds later (StunEvent) -
// the blow that ends the war, or one struck in its last seconds, died after EndWar had erased the war, and the
// engine took it for a murder: -2 000 rank to the killer (and his party) and an item drop of the victim. The
// owner, 13 October: "Po wyjsciu z wojny gildii punkty rangi gracza spadaja, nie powinny spadac."
static std::map<std::pair<DWORD, DWORD>, DWORD> s_mapMt2009WarEndedAt;

bool Mt2009GuildWarJustEnded(DWORD dwGuild1, DWORD dwGuild2)
{
	if (!dwGuild1 || !dwGuild2 || dwGuild1 == dwGuild2)
		return false;
	std::map<std::pair<DWORD, DWORD>, DWORD>::const_iterator it = s_mapMt2009WarEndedAt.find(std::make_pair(MIN(dwGuild1, dwGuild2), MAX(dwGuild1, dwGuild2)));
	return it != s_mapMt2009WarEndedAt.end() && get_global_time() - it->second <= 15;
}

void CGuild::EndWar(DWORD dwOppGID)
{

old:
if (pMap)
	pMap->SetEnded();

GuildWarPacket(dwOppGID, it->second.type, GUILD_WAR_END);
m_EnemyGuild.erase(it);

new:
if (pMap)
	pMap->SetEnded();

// MT2009_PLUS_WAR_RANK_KEEP_V1 (end): the war's end kept for the deaths still on their way.
s_mapMt2009WarEndedAt[std::make_pair(MIN(GetID(), dwOppGID), MAX(GetID(), dwOppGID))] = get_global_time();

GuildWarPacket(dwOppGID, it->second.type, GUILD_WAR_END);
m_EnemyGuild.erase(it);

if (g1 && g2)
	if (g1->UnderWar(g2->GetID()))
		isUnderGuildWar = true;

// MT2009_PLUS_WAR_RANK_KEEP_V1 (dead) (server-patches/warrankkeep): a death of a guild war is no murder,
// though it comes after the war's end - the victim falls three seconds after the killing blow (StunEvent),
// and the war that ends with it is erased by then (guild_war.cpp, Mt2009GuildWarJustEnded, 15 s) - nor is
// any death on a guild war arena (110, 111 and their copies: only the guilds at war fight there,
// MT2009_PLUS_GUILD_WAR_WATCH_V1). No rank lost by the killer or his party, no item dropped by the victim.
if (!isUnderGuildWar)
{
	bool Mt2009GuildWarJustEnded(DWORD dwGuild1, DWORD dwGuild2);
	const long lWarRankMap = GetMapIndex() >= 10000 ? GetMapIndex() / 10000 : GetMapIndex();
	if ((g1 && g2 && Mt2009GuildWarJustEnded(g1->GetID(), g2->GetID())) || lWarRankMap == 110 || lWarRankMap == 111)
	{
		isUnderGuildWar = true;
		sys_log(0, "WAR_RANK_KEEP: %s killed by %s on map %ld - a guild war's death, no rank penalty", GetName(), pkKiller->GetName(), GetMapIndex());
	}
}
